export interface AffordableHousingProperty {
  id: string;
  expirationDate: string;
  expirationYear: number;
  propertyName: string;
  address: string;
  city: string;
  county: string;
  totalUnits: number;
  restrictedUnits: number;
  ohcsFunded: boolean;
  usda: boolean;
  hud: boolean;
  ami30: number;
  ami40: number;
  ami50: number;
  ami60: number;
  ami70: number;
  ami80: number;
  preservationStatus: string;
  fundingSource: string;
  riskLevel: 'High' | 'Medium' | 'Low';
  daysUntilExpiration: number;
  investmentScore: number;
  leadStatus: 'New' | 'Researching' | 'Contacted' | 'Under Review' | 'Passed';
  notes: string;
}

function calculateDaysUntil(dateStr: string): number {
  const now = new Date('2026-10-04');
  const exp = new Date(dateStr);
  return Math.ceil((exp.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
}

function calcInvestmentScore(p: { totalUnits: number; riskLevel: string; daysUntilExpiration: number; ohcsFunded: boolean; hud: boolean; usda: boolean }): number {
  let score = 50;
  if (p.totalUnits >= 100) score += 20;
  else if (p.totalUnits >= 50) score += 15;
  else if (p.totalUnits >= 25) score += 10;
  if (p.riskLevel === 'High') score += 15;
  if (p.daysUntilExpiration <= 365) score += 10;
  else if (p.daysUntilExpiration <= 1095) score += 5;
  if (p.ohcsFunded) score += 5;
  if (p.hud) score -= 5;
  if (p.usda) score -= 3;
  return Math.min(100, Math.max(1, score));
}

function determineRisk(year: number, status: string, ohcs: boolean, hud: boolean, usda: boolean): 'High' | 'Medium' | 'Low' {
  if (status.includes('Government Owned') || status.includes('ROFR')) return 'Low';
  if (status.includes('Renewal In Process') || status.includes('Preservation in Process')) return 'Medium';
  if (year <= 2027) return 'High';
  if (year <= 2029 && !ohcs) return 'High';
  if (hud || usda) return 'Medium';
  if (year <= 2030) return 'High';
  return 'Medium';
}

function determineFunding(ohcs: boolean, hud: boolean, usda: boolean): string {
  const parts: string[] = [];
  if (ohcs) parts.push('LIHTC');
  if (hud) parts.push('HUD');
  if (usda) parts.push('USDA');
  return parts.length > 0 ? parts.join('/') : 'Other';
}

