export const affordableHousingData: AffordableHousingProperty[] = rawProperties.map((p, i) => {
  const year = new Date(p.expirationDate).getFullYear();
  const days = calculateDaysUntil(p.expirationDate);
  const risk = determineRisk(year, p.preservationStatus, p.ohcsFunded, p.hud, p.usda);
  const funding = determineFunding(p.ohcsFunded, p.hud, p.usda);
  const score = calcInvestmentScore({ totalUnits: p.totalUnits, riskLevel: risk, daysUntilExpiration: days, ohcsFunded: p.ohcsFunded, hud: p.hud, usda: p.usda });
  return {
    ...p,
    id: `AH-${String(i + 1).padStart(3, '0')}`,
    expirationYear: year,
    fundingSource: funding,
    riskLevel: risk,
    daysUntilExpiration: days,
    investmentScore: score,
    leadStatus: 'New' as const,
    notes: '',
  };
});

export const getUniqueCounties = (): string[] => [...new Set(affordableHousingData.map(p => p.county))].sort();
export const getUniqueYears = (): number[] => [...new Set(affordableHousingData.map(p => p.expirationYear))].sort();
export const getUniqueFundingSources = (): string[] => [...new Set(affordableHousingData.map(p => p.fundingSource))].sort();
export const getUniqueCities = (): string[] => [...new Set(affordableHousingData.map(p => p.city))].sort();
